static double ab(double x){return x<0?-x:x;}
static double mx(double a,double b){return a>b?a:b;}
__attribute__((export_name("fit"))) int fit(double *data,double *base,int n,double *out){double weights[100],errors[100],sorted[100];for(int i=0;i<n;i++)weights[i]=base[i];for(int iter=0;iter<4;iter++){double aa[16]={0},bb[12]={0};for(int j=0;j<n;j++){double *v=data+j*6,wt=weights[j],x=v[0],y=v[1],z=v[2],wx=wt*x,wy=wt*y,wz=wt*z;aa[0]+=wx*x;aa[1]+=wx*y;aa[2]+=wx*z;aa[3]+=wx;aa[5]+=wy*y;aa[6]+=wy*z;aa[7]+=wy;aa[10]+=wz*z;aa[11]+=wz;aa[15]+=wt;for(int k=0;k<3;k++){double e=v[3+k]*wt;int at=k*4;bb[at]+=e*x;bb[at+1]+=e*y;bb[at+2]+=e*z;bb[at+3]+=e;}}aa[4]=aa[1];aa[8]=aa[2];aa[12]=aa[3];aa[9]=aa[6];aa[13]=aa[7];aa[14]=aa[11];for(int a=0;a<4;a++)aa[a*4+a]+=.001;
for(int channel=0;channel<3;channel++){double m[4][5];for(int i=0;i<4;i++){for(int j=0;j<4;j++)m[i][j]=aa[i*4+j];m[i][4]=bb[channel*4+i];}for(int j=0;j<4;j++){int p=j;for(int k=j+1;k<4;k++)if(ab(m[k][j])>ab(m[p][j]))p=k;if(ab(m[p][j])<1e-10)return 0;for(int k=0;k<5;k++){double v=m[j][k];m[j][k]=m[p][k];m[p][k]=v;}double v=m[j][j];for(int k=j;k<=4;k++)m[j][k]/=v;for(int i=0;i<4;i++)if(i!=j){v=m[i][j];for(int k=j;k<=4;k++)m[i][k]-=v*m[j][k];}}for(int i=0;i<4;i++)out[channel*4+i]=m[i][4];}
for(int j=0;j<n;j++){double *v=data+j*6,s=0;for(int k=0;k<3;k++){double *m=out+k*4,e=m[0]*v[0]+m[1]*v[1]+m[2]*v[2]+m[3]-v[k+3];s+=e*e;}errors[j]=sorted[j]=__builtin_sqrt(s);}for(int j=1;j<n;j++){double v=sorted[j];int k=j-1;while(k>=0&&sorted[k]>v){sorted[k+1]=sorted[k];k--;}sorted[k+1]=v;}double sig=mx(.08,sorted[n>>1]*1.5);for(int j=0;j<n;j++){double q=sig/mx(.0001,errors[j]);if(q>1)q=1;weights[j]=base[j]*q*q;}}return 1;}
